	if err != nil {
		t.Fatalf("CreateSession: %v", err)
	}
	if sess.UserID != user.ID {
		t.Fatalf("CreateSession gave %+v", sess)
	}
	got, err := st.GetSession(token)
	if err != nil || got.UserID != user.ID {
		t.Fatalf("GetSession: %+v %v", got, err)
	}
	expired, err := store.NewToken(22)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := st.CreateSession(user.ID, expired, time.Now().UTC().Add(-time.Minute)); err != nil {
		t.Fatalf("CreateSession(expired): %v", err)
	}
