	if err != nil {
		t.Fatalf("CreateNote: %v", err)
	}
	if strings.Join(note.Tags, ",") != "go,work" {
		t.Fatalf("CreateNote tags = %v, want [go work] lower-cased and deduplicated", note.Tags)
	}
	if note.CreatedAt.IsZero() || note.UpdatedAt.IsZero() {
		t.Fatalf("CreateNote times %+v", note)
	}

	other, err := st.CreateUser("bob", "hash")
	if err != nil {
		t.Fatalf("CreateUser(bob): %v", err)
	}
	if _, err := st.GetNote(note.ID, other.ID); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("another user's GetNote: %v, want ErrNotFound", err)
	}
	if _, err := st.UpdateNote(note.ID, other.ID, "x", "y", nil); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("another user's UpdateNote: %v, want ErrNotFound", err)
	}
	if err := st.DeleteNote(note.ID, other.ID); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("another user's DeleteNote: %v, want ErrNotFound", err)
	}
	if _, err := st.PinNote(note.ID, other.ID); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("another user's PinNote: %v, want ErrNotFound", err)
	}

	updated, err := st.UpdateNote(note.ID, user.ID, "Edited", "new body", []string{"home"})
	if err != nil {
		t.Fatalf("UpdateNote: %v", err)
	}
	if updated.Title != "Edited" || strings.Join(updated.Tags, ",") != "home" {
		t.Fatalf("UpdateNote gave %+v", updated)
